import React, { useEffect, useMemo, useState } from "react";
import mistersun from "../assets/mistersun.png"; // adjust path if needed


// Berkeley (roughly campus)
const BERKELEY = { lat: 37.8715, lng: -122.2730 };

function fmtTime(date, timeZone = "America/Los_Angeles") {
  return new Intl.DateTimeFormat("en-US", {
    timeZone,
    hour: "numeric",
    minute: "2-digit",
  }).format(date);
}

function fmtDeltaMinutes(totalMinutes) {
  const sign = totalMinutes >= 0 ? "+" : "−";
  const abs = Math.abs(totalMinutes);
  const h = Math.floor(abs / 60);
  const m = abs % 60;
  return h > 0 ? `${sign}${h}h ${m}m` : `${sign}${m}m`;
}

async function fetchSunTimesUTC({ lat, lng }, dateISO /* YYYY-MM-DD or null */) {
  // sunrise-sunset.org returns times in UTC by default; we convert client-side
  const url = new URL("https://api.sunrise-sunset.org/json");
  url.searchParams.set("lat", String(lat));
  url.searchParams.set("lng", String(lng));
  url.searchParams.set("formatted", "0"); // ISO timestamps
  if (dateISO) url.searchParams.set("date", dateISO);

  const res = await fetch(url.toString());
  if (!res.ok) throw new Error(`Sun API error (${res.status})`);
  const data = await res.json();
  if (data.status !== "OK") throw new Error(`Sun API status: ${data.status}`);
  return data.results; // contains .sunset, .sunrise, etc (ISO in UTC)
}

export default function SunsetWidget({
  lat = BERKELEY.lat,
  lng = BERKELEY.lng,
  timeZone = "America/Los_Angeles",
  title = "Berkeley sunset",
  showDelta = true,
}) {
  const [loading, setLoading] = useState(true);
  const [err, setErr] = useState("");
  const [sunsetToday, setSunsetToday] = useState(null);
  const [deltaMinutes, setDeltaMinutes] = useState(null);

  const todayISO = useMemo(() => {
    // Use local “today” in the chosen TZ
    const now = new Date();
    const parts = new Intl.DateTimeFormat("en-CA", {
      timeZone,
      year: "numeric",
      month: "2-digit",
      day: "2-digit",
    }).formatToParts(now);
    const y = parts.find(p => p.type === "year")?.value;
    const m = parts.find(p => p.type === "month")?.value;
    const d = parts.find(p => p.type === "day")?.value;
    return `${y}-${m}-${d}`;
  }, [timeZone]);

  const yesterdayISO = useMemo(() => {
    const [y, m, d] = todayISO.split("-").map(Number);
    const dt = new Date(Date.UTC(y, m - 1, d));
    dt.setUTCDate(dt.getUTCDate() - 1);
    const yy = dt.getUTCFullYear();
    const mm = String(dt.getUTCMonth() + 1).padStart(2, "0");
    const dd = String(dt.getUTCDate()).padStart(2, "0");
    return `${yy}-${mm}-${dd}`;
  }, [todayISO]);

  useEffect(() => {
    let cancelled = false;

    async function run() {
      setLoading(true);
      setErr("");
      try {
        const today = await fetchSunTimesUTC({ lat, lng }, todayISO);
        const sunsetDateToday = new Date(today.sunset); // ISO UTC -> Date
        if (!cancelled) setSunsetToday(sunsetDateToday);

        if (showDelta) {
          const yday = await fetchSunTimesUTC({ lat, lng }, yesterdayISO);
          const sunsetDateYday = new Date(yday.sunset);

          const diffMs = sunsetDateToday.getTime() - sunsetDateYday.getTime();
          const diffMin = Math.round(diffMs / 60000);
          if (!cancelled) setDeltaMinutes(diffMin);
        }
      } catch (e) {
        if (!cancelled) setErr(e?.message || "Failed to load sunset time.");
      } finally {
        if (!cancelled) setLoading(false);
      }
    }

    run();
    return () => {
      cancelled = true;
    };
  }, [lat, lng, timeZone, todayISO, yesterdayISO, showDelta]);

  return (
    <div className="sunset-widget sunset-main" role="status" aria-live="polite">
      <div className="sunset-widget__content">
        <div className="sunset-widget__title">{title}</div>
  
        {loading ? (
          <div className="sunset-widget__value">Loading...</div>
        ) : err ? (
          <div className="sunset-widget__error">⚠ {err}</div>
        ) : (
          <>
            <div className="sunset-widget__value">
              <img src={mistersun} alt="sun setting" className="sunset-sun" />
              <span>{fmtTime(sunsetToday, timeZone)}</span>
            </div>
  
            {showDelta && deltaMinutes != null && (
              <div className="sunset-widget__delta">
                vs yesterday: <span>{fmtDeltaMinutes(deltaMinutes)}</span>
              </div>
            )}
  
            <div className="sunset-widget__meta">
              {todayISO} • {timeZone.replace("_", " ")}
            </div>
          </>
        )}
      </div>
    </div>
  );
  
}